<?php
declare(strict_types=1);
$root=__DIR__;$probe=json_decode((string)@file_get_contents($root.'/runtime/system-probe.json'),true)?:[];$error='';$done=is_file($root.'/runtime/request.json');
function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function validPath(string $p):array{if($p===''||$p[0]!=='/')return[false,'Pfad muss absolut sein.'];if(file_exists($p)||is_link($p))return[false,'Der Zielordner darf noch nicht existieren.'];$parent=dirname($p);if(!is_dir($parent))return[false,'Der Elternordner existiert nicht.'];if(!is_writable($parent))return[false,'Der Elternordner ist nicht beschreibbar.'];if(in_array($p,['/','/etc','/usr','/var','/var/www','/var/www/html'],true))return[false,'Dieser System- oder DocumentRoot-Pfad ist nicht zulässig.'];return[true,'OK'];}
if($_SERVER['REQUEST_METHOD']==='POST'&&!$done){$path=rtrim((string)($_POST['path']??''),'/');[$ok,$msg]=validPath($path);if(!$ok)$error=$msg;elseif(strlen((string)($_POST['password']??''))<12)$error='Passwort muss mindestens 12 Zeichen besitzen.';else{$request=['token'=>(string)($_POST['token']??''),'path'=>$path,'username'=>trim((string)$_POST['username']),'email'=>trim((string)$_POST['email']),'passwordHash'=>password_hash((string)$_POST['password'],PASSWORD_ARGON2ID),'createdAt'=>gmdate('c')];file_put_contents($root.'/runtime/request.json',json_encode($request,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);$done=true;}}
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WAMS Installation</title><style>body{font:15px system-ui;background:#f3f5f7;color:#15202b;margin:0}.w{max-width:900px;margin:40px auto;padding:20px}.c{background:#fff;border:1px solid #dce3e8;border-radius:14px;padding:22px;margin:16px 0}input,button{width:100%;padding:11px;margin:6px 0 14px;box-sizing:border-box}button{background:#1769aa;color:#fff;border:0;border-radius:8px}.ok{color:#18794e}.bad{background:#ffe8e5;padding:12px}.g{display:grid;grid-template-columns:1fr 1fr;gap:12px}code{word-break:break-all}</style></head><body><main class="w"><h1>WAMS installieren</h1><?php if($done):?><section class="c"><h2 class="ok">Anforderung angenommen</h2><p>Der Terminalprozess richtet jetzt den endgültigen Pfad und Apache ein. Diese Seite kann nach der Terminalmeldung geschlossen werden.</p></section><?php else:?><?php if($error):?><div class="bad"><?=h($error)?></div><?php endif?><section class="c"><h2>Erkannter Systemzustand</h2><div class="g"><div><strong>Apache</strong><p><?=h($probe['apache']['installed']?'vorhanden':'fehlt und wird installiert')?>, <?=h($probe['apache']['version']??'-')?></p></div><div><strong>PHP</strong><p><?=h($probe['php']['installed']?'vorhanden':'fehlt und wird installiert')?>, <?=h($probe['php']['version']??'-')?></p></div></div><p><strong>Vorhandene DocumentRoots:</strong><br><code><?=h(implode(', ',$probe['apache']['documentRoots']??[]))?></code></p><p><strong>Installierte fehlende Komponenten:</strong> <?=h(implode(', ',$probe['installedByWams']??[])?:'keine')?></p></section><section class="c"><h2>Ziel und erster Administrator</h2><form method="post"><input type="hidden" name="token" value="<?=h($_GET['token']??'')?>"><label>Neuer, noch nicht vorhandener Zielordner</label><input name="path" value="<?=h($probe['suggestedPath']??'/var/www/html/web-application-management-system')?>" required><small>Der vorgeschlagene Unterordner basiert auf einem erkannten DocumentRoot. Er wird erst nach Zustimmung angelegt.</small><label>Benutzername</label><input name="username" required><label>E-Mail</label><input type="email" name="email" required><label>Passwort</label><input type="password" name="password" minlength="12" required><button>Systemzustand bestätigen und installieren</button></form></section><?php endif?></main></body></html>
